"""Trend family: long-flat Donchian ensemble over [20, 40, 80, 160] candles, entering at a score of 0.5, leaving at 0.0, stake cut to a 40% vol target."""

from pandas import DataFrame

from freqtrade.strategy import IStrategy
from lab import channels


class TrendDonchian_15m(IStrategy):
    INTERFACE_VERSION = 3
    timeframe = "15m"
    can_short = False
    startup_candle_count = 200
    minimal_roi = {"0": 100}
    stoploss = -0.0306
    lookbacks = [20, 40, 80, 160]

    def populate_indicators(self, dataframe: DataFrame, metadata: dict) -> DataFrame:
        dataframe["score"] = channels.donchian_score(dataframe["close"], self.lookbacks)
        dataframe["scale"] = channels.vol_scale(dataframe["close"], 0.4, 30, 35040)
        return dataframe

    def populate_entry_trend(self, dataframe: DataFrame, metadata: dict) -> DataFrame:
        dataframe.loc[(dataframe["score"] >= 0.5) & dataframe["scale"].notna() & (dataframe["volume"] > 0), "enter_long"] = 1
        return dataframe

    def populate_exit_trend(self, dataframe: DataFrame, metadata: dict) -> DataFrame:
        dataframe.loc[dataframe["score"] <= 0.0, "exit_long"] = 1
        return dataframe

    def custom_stake_amount(self, pair: str, current_time, current_rate, proposed_stake, min_stake, max_stake,
                            leverage, entry_tag, side, **kwargs) -> float:
        """The proposed stake times the vol scale and the ensemble score on the signal candle."""
        df, _ = self.dp.get_analyzed_dataframe(pair, self.timeframe)
        if df.empty:
            return proposed_stake
        last = df.iloc[-1]
        return min(max(proposed_stake * float(last["scale"]) * float(last["score"]), min_stake or 0.0), max_stake)
